152	interface ReceiptBase<T> {
153		readonly schema: 'guessless.receipt/v1';
154		readonly query: string;
155		readonly request: QueryRequest;
156		readonly snapshot: string;
157		readonly results: readonly T[];
158		readonly integrity: string;
159	}
160	
161	export interface CompleteReceipt<T> extends ReceiptBase<T> {
162		readonly state: 'complete';
163	}
164	export interface PartialReceipt<T> extends ReceiptBase<T> {
165		readonly state: 'partial';
166		readonly unresolved: readonly UnresolvedSite[];
167	}
168	export interface RefusedReceipt<T> extends ReceiptBase<T> {
169		readonly state: 'refused';
170		readonly reason: UnresolvedReason;
171		readonly detail: string;
172	}
173	export type Receipt<T> = CompleteReceipt<T> | PartialReceipt<T> | RefusedReceipt<T>;
174	type WithoutIntegrity<T> = T extends unknown ? Omit<T, 'integrity'> : never;
175	type UnsignedReceipt<T> = WithoutIntegrity<Receipt<T>>;
176	
177	const baseKeys = ['query', 'request', 'results', 'schema', 'snapshot', 'state'] as const;
178	const anchorKeys = ['file', 'fingerprint', 'schema', 'semanticPath'] as const;
179	
180	export function makeReceipt<T>(receipt: UnsignedReceipt<T>): Receipt<T> {
181		assertReceiptShape(receipt);
182		return { ...receipt, integrity: sha256(receipt) } as Receipt<T>;
183	}
184	
185	export function verifyReceipt(value: unknown, currentSnapshot?: string): value is Receipt<unknown> {
186		try {
187			assertReceiptShape(value);
188			const record = value as Record<string, unknown>;
